import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const promptBuilder = new PromptBuilder({identity: 'Usage acceptance test.'});
const session = (): ChatSession => ({
  sessionId: 'usage-session',
  userId: 'usage-user',
  entries: [{role: 'user', content: 'Use the tools.', timestamp: '2026-01-01T00:00:00.000Z'}],
});

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'lookup-1', name: 'lookup', input: {}}};
const TOOL_STOP: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
const DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;

  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield* rounds[round++] ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const lookupRegistry = (): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'lookup', description: 'Looks up a value.', inputSchema: {type: 'object'}},
    async () => 'found'
  );
  return registry;
};

const usageStop = (stopReason: string, usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason, usage});

describe('afterModelResponse usage across tool rounds', () => {
  it('reports the summed usage from every provider call in a turn with two tool rounds', async () => {
    let reported: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reported = usage;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 11, outputTokens: 2, totalTokens: 13})],
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 23, outputTokens: 3, totalTokens: 26})],
        [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 37, outputTokens: 5, totalTokens: 42})],
      ]),
      promptBuilder,
      lookupRegistry(),
      {hooks}
    );

    await orchestrator.processMessage(session());

    expect(reported).toEqual({inputTokens: 71, outputTokens: 10, totalTokens: 81});
  });

  it('counts reported rounds while leaving a turn with no reported usage undefined', async () => {
    const reports: Array<UsageMetadata | undefined> = [];
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reports.push(usage);
      },
    };
    const withGaps = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 2, outputTokens: 1, totalTokens: 3})],
        [TOOL_CALL, TOOL_STOP],
        [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 7, outputTokens: 4, totalTokens: 11})],
      ]),
      promptBuilder,
      lookupRegistry(),
      {hooks}
    );
    const withoutUsage = createChatOrchestrator(
      scriptedProvider([[{type: 'text', text: 'Done.'}, DONE]]),
      promptBuilder,
      undefined,
      {hooks}
    );

    await withGaps.processMessage(session());
    await withoutUsage.processMessage(session());

    expect(reports).toEqual([{inputTokens: 9, outputTokens: 5, totalTokens: 14}, undefined]);
  });
});
import type {ChatSession} from '../types/session.js';
import type {ToolRegistry, ToolContext, ToolResponse} from './tools/registry.js';
import type {
  AIProvider,
  Message,
  MessageChunk,
  SendMessageParams,
  ToolCall,
  ToolResultContent,
  TotalUsageMetadata,
  UsageMetadata,
} from '../types/ai.js';
import type {OutgoingMessage} from '../types/messages.js';
import type {PromptBuilder, PromptBuilderOptions} from '../infrastructure/builders/promptBuilder.js';
import type {SessionStore} from '../types/sessionStore.js';
import {toMessages, createContextConfig} from './conversationContext.js';
import type {ContextConfig} from './conversationContext.js';
import {
  shouldContinueToolLoop,
  collectText,
  buildToolCallMessages,
  collectToolCalls,
  extractStopReason,
  extractUsage,
} from './orchestratorHelpers.js';
import {appendEntry, commitStreamingEntries} from './entryMutations.js';
import {log} from '../shared/logger.js';

const DEFAULT_MAX_TOOL_ROUNDS = 5;

export interface OrchestratorHooks {
  beforeSession?: (session: ChatSession) => Promise<void>;
  afterSession?: (session: ChatSession) => Promise<void>;
  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
  afterModelResponse?: (session: ChatSession, responseText: string, totalUsage?: TotalUsageMetadata) => Promise<void>;
  onError?: (session: ChatSession, error: Error) => Promise<void>;
  /** The supported seam for an EU AI Act Art. 14 human-oversight control: fires before each known tool's executor, and a returned ToolResponse replaces the call (see docs/adding-a-tool.md); it receives the model's raw tool input and, through session, the caller's authHeaders, so a policy that logs either logs personal data and credential material; the engine asserts nothing about any policy installed here. */
  beforeToolCall?: (session: ChatSession, call: ToolCall) => Promise<ToolResponse | undefined>;
  /** Fires when the model asks for a tool round the budget refuses, after the last provider call and before afterModelResponse; a returned string reaches the user as the turn's closing text, and the engine writes none of its own (see specs/hal-engine-tool-budget/spec.md). */
  onToolBudgetExhausted?: (session: ChatSession, budget: ToolBudgetInfo) => Promise<string | undefined>;
}

export interface ToolBudgetInfo {
  maxToolRounds: number;
  requestedTools: string[];
}

type BeforeToolCall = NonNullable<OrchestratorHooks['beforeToolCall']>;
type OnToolBudgetExhausted = NonNullable<OrchestratorHooks['onToolBudgetExhausted']>;

export const TOOL_BUDGET_EXHAUSTED = 'tool_budget_exhausted';

export interface ChatOrchestrator {
  processMessage(session: ChatSession): Promise<string>;
  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
}

export interface ChatOrchestratorOptions {
  maxToolRounds?: number;
  contextConfig?: Partial<ContextConfig>;
  promptBuilderOptions?: PromptBuilderOptions;
  hooks?: OrchestratorHooks;
  sessionStore?: SessionStore;
}

interface ToolExecutionResult {
  clientMessages: OutgoingMessage[];
  suppressOutput: boolean;
}
export function createChatOrchestrator(
  provider: AIProvider,
  promptBuilder: PromptBuilder,
  toolRegistry?: ToolRegistry,
  options?: ChatOrchestratorOptions
): ChatOrchestrator {
  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
  const contextConfig = createContextConfig(options?.contextConfig);
  const toolInstructions = toolRegistry?.getPromptInstructions();
  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
  const tools = toolRegistry?.getDefinitions();
  const hooks = options?.hooks;
  const sessionStore = options?.sessionStore;

  return {
    async processMessage(session: ChatSession): Promise<string> {
      return collectText(this.processMessageStream(session));
    },

    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
      try {
        if (hooks?.beforeSession) await hooks.beforeSession(session);

        let userMessage = lastUserContent(session);

        if (hooks?.beforeUserInput) {
          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
        }

        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);

        const systemPrompt = hooks?.beforeModelResponse
          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
          : baseSystemPrompt;

        const messages: Message[] = toMessages(session.entries, contextConfig);
        let totalUsage: TotalUsageMetadata | undefined;
        let responseText = '';

        // Bounded by the budget gate below, not the header: maxToolRounds executed rounds, maxToolRounds + 1 provider calls.
        for (let round = 0; ; round++) {
          log.info('orchestrator', 'starting round', {round});
          const pendingToolCalls: ToolCall[] = [];

          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
          responseText += outcome.text;
          if (outcome.usage) {
            totalUsage = {
              inputTokens: (totalUsage?.inputTokens ?? 0) + outcome.usage.inputTokens,
              outputTokens: (totalUsage?.outputTokens ?? 0) + outcome.usage.outputTokens,
              totalTokens: (totalUsage?.totalTokens ?? 0) + outcome.usage.totalTokens,
            };
          }

          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
          if (budgetSpent(round, maxToolRounds, pendingToolCalls)) {
            const budget = {maxToolRounds, requestedTools: pendingToolCalls.map(tc => tc.name)};
            responseText += yield* closeExhaustedTurn(session, budget, hooks?.onToolBudgetExhausted);
            break;
          }

          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
          const {clientMessages, suppressOutput} = await executeToolCalls(
            pendingToolCalls,
            messages,
            session,
            toolCallRunner(toolRegistry!, session, hooks?.beforeToolCall)
          );
          log.info('orchestrator', 'tool execution complete', {
            clientMessageCount: clientMessages.length,
            clientMessageTypes: clientMessages.map(m => m.type),
            suppressOutput,
          });

          if (clientMessages.length > 0) {
            yield {type: 'tool_result' as const, clientMessages};
          }

          if (suppressOutput) {
            yield {type: 'suppress_output' as const};
          }
        }

        if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, totalUsage);
      } catch (error) {
        if (hooks?.onError && error instanceof Error) {
          await hooks.onError(session, error);
        }
        throw error;
      } finally {
        // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
        commitStreamingEntries(session);
        try {
          if (hooks?.afterSession) await hooks.afterSession(session);
        } finally {
          await saveSession(sessionStore, session);
        }
      }
    },
  };
}

// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
function normalizeToolRounds(value: number | undefined): number {
  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
  return Math.max(0, Math.floor(value));
}

// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
  if (round < maxToolRounds) return false;
  log.warn('orchestrator', 'tool budget exhausted', {
    maxToolRounds,
    requestedTools: pendingToolCalls.map(tc => tc.name),
  });
  return true;
}

// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
async function* closeExhaustedTurn(
  session: ChatSession,
  budget: ToolBudgetInfo,
  hook?: OnToolBudgetExhausted
): AsyncGenerator<MessageChunk, string> {
  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
  if (sentence !== '') yield {type: 'text', text: sentence};
  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
  return sentence;
}

interface RoundOutcome {
  stopReason: string;
  text: string;
  usage?: UsageMetadata;
}

// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
async function* streamRound(
  provider: AIProvider,
  request: SendMessageParams,
  pendingToolCalls: ToolCall[]
): AsyncGenerator<MessageChunk, RoundOutcome> {
  let stopReason = '';
  let text = '';
  let usage: UsageMetadata | undefined;

  for await (const chunk of provider.sendMessage(request)) {
    yield chunk;
    collectToolCalls(chunk, pendingToolCalls);
    stopReason = extractStopReason(chunk) ?? stopReason;
    usage = extractUsage(chunk) ?? usage;
    if (chunk.type === 'text') text += chunk.text;
  }

  return {stopReason, text, usage};
}

// A changed message is also written back to the session's last user entry.
async function rewriteUserMessage(
  session: ChatSession,
  userMessage: string,
  hook: (session: ChatSession, userMessage: string) => Promise<string>
): Promise<string> {
  const modified = await hook(session, userMessage);
  if (modified === userMessage) return userMessage;

  updateLastUserContent(session, modified);
  return modified;
}
import type {OutgoingMessage} from './messages.js';

export interface TextMessage {
  role: 'user' | 'assistant';
  content: string;
}

export interface ToolCallContent {
  type: 'tool_use';
  toolUseId: string;
  name: string;
  input: Record<string, unknown>;
}

export interface ToolResultContent {
  type: 'tool_result';
  toolUseId: string;
  content: string;
}

export interface ToolUseMessage {
  role: 'assistant';
  content: ToolCallContent[];
}

export interface ToolResultMessage {
  role: 'user';
  content: ToolResultContent[];
}

export type Message = TextMessage | ToolUseMessage | ToolResultMessage;

export interface ToolDefinition {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
  promptInstructions?: string;
  examplePrompts?: string[];
}

export interface ToolCall {
  id: string;
  name: string;
  input: Record<string, unknown>;
}

export type MessageChunk =
  | {type: 'text'; text: string}
  | {type: 'tool_use'; toolCall: ToolCall}
  | {type: 'tool_result'; clientMessages: OutgoingMessage[]}
  | {type: 'suppress_output'}
  | {type: 'stop'; stopReason: string; usage?: UsageMetadata};

export interface SendMessageParams {
  messages: Message[];
  systemPrompt: string;
  tools?: ToolDefinition[];
  maxTokens?: number;
}

export interface StructuredOutputParams<_T> {
  messages: Message[];
  systemPrompt: string;
  responseSchema: ResponseSchema;
  maxTokens?: number;
}

export interface ResponseSchema {
  type: 'object' | 'array' | 'string' | 'number' | 'boolean';
  properties?: Record<string, ResponseSchema>;
  items?: ResponseSchema;
  required?: string[];
  description?: string;
  enum?: string[];
}

export interface UsageMetadata {
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
}

export type TotalUsageMetadata = UsageMetadata;

export interface AIProviderResponse {
  usage?: UsageMetadata;
}

export interface AIProvider {
  sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk>;
  generateStructured<T>(params: StructuredOutputParams<T>): Promise<T>;
}

export class AIError extends Error {
  constructor(
    message: string,
    public readonly code: string,
    // eslint-disable-next-line re-lint/no-flag-params -- public API; splitting AIError is a breaking change (adrs/ADR-006-lint-suppressions.md)
    public readonly retryable: boolean = false
  ) {
    super(message);
    this.name = 'AIError';
  }
}
# Config-Installed Orchestrator Hooks

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#36 |
| Status | Shipped              |

`OrchestratorHooks` is the engine's only lifecycle seam, and `HalEngineConfig.orchestrator.hooks` is the supported way to install it: `createHalEngine` forwards the set to `createChatOrchestrator`, so a hook a deployer passes through the factory reaches the running orchestrator rather than sitting unread on the config object. This spec pins that forwarding and the measured semantics the seam already carries, so the hook-based features that follow in this epic — transparency disclosure, audit and usage recording, human oversight, provider failover — specify against real behaviour rather than against what the hook names suggest.

## Installing hooks through config

- A hook passed through `orchestrator.hooks` is forwarded to the orchestrator and fires ([validated by: forwards an orchestrator hook, so one passed through the config actually fires](../../src/config.test.ts#L19)).
- An engine built with no `orchestrator` key at all still processes a message, so the field is optional in fact and not only in the type ([validated by: processes a message when the config declares no orchestrator key at all](../../src/config.test.ts#L95)).
- A `beforeModelResponse` hook installed through config is handed the base system prompt built from `prompt`, proving the hook reaches the orchestrator and is wired into the prompt pipeline rather than only being stored on the config ([validated by: hands a config-installed beforeModelResponse hook the built base system prompt, not merely storing it](../../src/config.test.ts#L108)).
- The value the hook returns then replaces the system prompt the provider receives; this is exercised at the orchestrator layer because `HalEngineConfig.provider` takes a `ProviderConfig` and offers no seam to inject a recording provider through config ([validated by: replaces system prompt with returned value](../../src/orchestration/chatOrchestrator.test.ts#L221)).
- For a session that completes without error the hooks fire in the order `beforeSession` → `beforeUserInput` → `afterUserInput` → `beforeModelResponse` → `afterModelResponse` → `afterSession` ([validated by: fires the lifecycle hooks in documented order for a session that completes without error](../../src/config.test.ts#L132)).
- A `beforeSession` that throws reaches the caller as a rejection, and also runs `onError` with the thrown error and then `afterSession`, because the call sits inside the same `try`/`finally` as the rest of the turn. An `afterSession` hook called under this condition can infer the session never advanced past `beforeSession`: no user-input hooks ran, no model response was generated, and no tool rounds were started — a cleanup hook that allocates in `beforeSession` and frees in `afterSession` will therefore always see the allocation and the release on the same error path ([validated by: runs onError then afterSession when it throws, and still rejects to the caller](../../src/orchestration/chatOrchestrator.test.ts#L116)).

## Engine startup

- The engine's `start()` method rejects the returned promise when it cannot bind the configured port, rather than emitting an unhandled error event that would take the process down ([validated by: rejects instead of taking the process down with an unhandled error event](../../src/config.test.ts#L174)).

## Measured semantics — out of scope

These properties of `src/orchestration/chatOrchestrator.ts` record the measured semantics that hook features specify against. The `onError` boundary remains out of scope; issue #93 defines the aggregate usage delivered after tool rounds.

- The `catch` gates `onError` on `error instanceof Error` ([chatOrchestrator.ts#L150](../../src/orchestration/chatOrchestrator.ts#L150)), so a rejection that is not an `Error` — a thrown string or object — bypasses `onError` entirely while still propagating to the caller.
- `afterModelResponse` is called once per user message after the round loop exits and receives `TotalUsageMetadata`, the summed provider-call usage for the entire turn, so its public type says that tool rounds are included in a deployer's billing or audit total ([validated by: reports total usage across every provider call](../../src/orchestration/chatOrchestrator.test.ts#L550), [validated by: reports the summed usage from every provider call in a turn with two tool rounds](../../src/orchestration/chatOrchestratorUsage.acceptance.test.ts#L44)).
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | Implemented          |

`ToolRegistry.execute` validates the caller-supplied `input` against the tool's declared `inputSchema` before invoking the executor. A failure returns a `ToolResponse` describing the constraint violation so the model can read it and attempt a corrected call within the existing tool-round budget; it never throws, because a throw propagates out of the orchestrator's `Promise.all` and ends the whole conversation with a transport error rather than giving the model a chance to recover.

## Validation contract

- `execute` validates `input` against the resolved tool definition's `inputSchema` before calling the executor; on failure it returns a `ToolResponse` whose `result` describes the failure, and the executor is never invoked ([validated by: returns a ToolResponse naming the missing required field and does not invoke the executor](../../src/orchestration/tools/registry.test.ts#L7)).
- Valid input passes through to the executor unchanged; extra properties that are present in `input` but absent from the schema are forwarded without modification ([validated by: passes valid input with an extra property through to the executor unchanged](../../src/orchestration/tools/registry.test.ts#L30)).
- Validation enforces `required`, declared types, and `enum` constraints only — it does not inject `additionalProperties: false`, coerce types, or apply defaults ([validated by: passes valid input with an extra property through to the executor unchanged](../../src/orchestration/tools/registry.test.ts#L30)).
- A wrong-typed field is rejected with a message naming the field path and the expected type; the offending value does not appear in the rejection text or in any log line produced during the call ([validated by: rejects a call whose field type is wrong, naming the field path and expected type but not the value](../../src/orchestration/tools/registry.test.ts#L50), [validated by: does not include the rejected field value in the returned text or any log line](../../src/orchestration/tools/registry.test.ts#L112)).
- `execute` still throws `Error('Unknown tool: <name>')` for an unregistered name, unchanged — a missing tool name is a programming error in the caller, not a model input to be corrected ([validated by: throws for an unregistered tool name](../../src/orchestration/tools/registry.test.ts#L106)).

## Schema compilation

- A static tool's `inputSchema` is compiled at `register` time; an uncompilable schema causes `register` to throw synchronously with a message that names the tool, so a broken schema fails at startup rather than mid-conversation ([validated by: throws at register time when the inputSchema is uncompilable and the message names the tool](../../src/orchestration/tools/registry.test.ts#L70)).
- A function-valued `ToolDefinitionSource` is resolved on each `execute` call; the schema validated against is the schema returned by that call, not the one resolved at `register` time ([validated by: validates each call against the schema the definition function returns at that call](../../src/orchestration/tools/registry.test.ts#L81)).

## Orchestrator integration

- A validation failure becomes a tool result (not a thrown error), so the orchestrator delivers the rejection text to the model and the model can attempt a corrected call; `DEFAULT_MAX_TOOL_ROUNDS = 5` is the bound that stops a retry cycle from spinning ([validated by: resolves processMessage and makes the validation-rejection text visible to the provider on the next round](../../src/orchestration/chatOrchestrator.test.ts#L550)).

## Out of scope

Validating tool output, hallucination detection, per-tool authorisation, retry and rate limiting around tool execution, and the `Unknown tool: <name>` throw becoming a tool result (tracked separately).
# Changelog

All notable changes to `@re-cinq/hal-engine` are documented here.

The format is [Keep a Changelog 1.1.0](https://keepachangelog.com/en/1.1.0/), and this project adheres to
[Semantic Versioning](https://semver.org/spec/v2.0.0.html). Entries are written for somebody installing the
package, not for somebody reading this repository's commit log.

## [Unreleased]

### Added

- `SessionStore` gains an optional `save(session)` member: the write signal a durable store needs. The engine calls it once per processed user message, from the same `finally` path that runs `afterSession`, so it fires for a turn that ended in a provider error as well as one that succeeded — a store that only heard about successes would lose exactly the conversations a customer complains about. By the time it runs, the turn's entries are committed, so the assistant entry's `isStreaming` is already `false` — including when a provider threw mid-stream, where the engine now closes the open entry before saving, recording `truncated` on it, rather than persisting a half-streamed entry that looks finished. An `afterSession` hook that throws no longer costs the turn its write signal. What `save` throws or rejects with is caught and logged as one line carrying the session id, and the turn continues: the client still receives its full stream and `stream_end`, because a database outage is not a reason for the agent to stop answering. The member is typed `void | Promise<void>`, so a synchronous implementation and an `async` one both satisfy it. Additive: `InMemorySessionStore` does not implement `save` and is unchanged, and a store that omits it behaves exactly as before.
- `SessionStore` gains an optional `evict(sessionId)` member, and `InMemorySessionStore` implements it. The engine calls it only for a session whose socket closed while `create` was still pending — one that no client ever received and that has no entries to keep. `InMemorySessionStore` now also takes `{maxAgeMs}` (default `28_800_000`, eight hours), exported as `InMemorySessionStoreOptions`. Expired sessions are evicted when read and swept at the head of `create`, which stops at the first live session, so the bound costs nothing on a busy store. There is no timer: a library-owned interval would keep your process alive.
- **`MongoSessionStore`**, a durable session store, exported as `MongoSessionStore` and `createMongoSessionStore`. It takes a collection, a client with a database name, or a connection URL — nothing in the package reads the environment or assumes a host. The collection is the truth and the in-process cache is an optimisation: a session written by `save` is readable by a second store on the same collection. `delete` removes the document — it is the consumer's erasure primitive and the engine never calls it — as do `eraseConversation`, `eraseOlderThan(cutoff)` and `eraseAll`, while `clear` alone touches only the cache; `docs/session-stores.md` opens with the table that says which is which, because the previous documentation would have led you to believe `delete` erased. Documents carry `createdAt` and `updatedAt`, so a retention period is expressible without per-entry timestamps. **No credential is ever written**: `authHeaders`, `authorization`, `cookie` and `host` are stripped at any depth, not just the top level, and the same `stripCredentialKeys` is exported for stores you write yourself. `mongodb` is an optional peer dependency loaded only when the store actually connects, so a consumer who installs no optional peer can still import the package root and use the in-memory store. **Migration note**: `delete` and `evict` both erase on this store, so the one-line `onDisconnect: sessionId => store.delete(sessionId)` that restores the pre-0.4 close behaviour destroys the conversation on every socket close — point `onDisconnect` at neither. Nothing needs reclaiming by hand: the in-process cache is bounded by `maxAgeMs` (eight hours by default) and drops stale entries without touching a document. This does **not** deliver conversation resume, and it does not make the engine safe to run as more than one instance against one conversation.

### Changed

- Every `SessionStore` member is now `Awaitable<T>` (`T | Promise<T>`) rather than a bare `T`, so a store backed by a database is expressible for the first time. `Awaitable` is exported from the package root. **A synchronous implementation needs no change** — `T` is assignable to `T | Promise<T>` in a return position — and `InMemorySessionStore` is unedited. The WebSocket connection handler now awaits `create` and the release that follows a close: it pauses the socket across the await so a frame sent before `connected` arrives is buffered rather than dropped, attaches its `close` listener before the await so a socket that closes mid-create leaves no session behind, and catches a rejection from either call so one store failure closes one socket instead of ending the process with an unhandled rejection. **Migration note**: the `connected` frame now arrives one tick later, after the awaited `create`, so a client that waits for it (as the protocol already requires) sees no difference; only code that assumed the frame was emitted synchronously with the upgrade does.
- **The engine no longer erases a conversation when its socket closes.** The WebSocket close handler called `sessionStore.delete(sessionId)` unconditionally, which meant that behind a durable store every conversation was written and then destroyed the moment the customer closed their tab — the opposite of what this engine's own documentation promised. `SessionStore.delete` now has no engine-internal caller at all and is purely your erasure primitive. The credentials the socket carried are cleared from the session on close, since they were issued for a request that is over; the entries are untouched. **Migration note**: to restore the old behaviour exactly, pass `onDisconnect: sessionId => store.delete(sessionId)` — that one line is the whole migration. If you rely on the default store not growing, note that it is now bounded by `maxAgeMs` (eight hours) rather than by the close handler; that is a memory bound, not a retention policy, and the retention decision remains yours.

### Fixed

- `onError` and `afterSession` hooks now fire when `beforeSession` throws, matching the guarantee the hook names imply. Previously, a throw from `beforeSession` escaped the `try`/`finally` block entirely, so neither hook ran. **Migration note**: if your `afterSession` hook assumed it would only be called after a full session turn, it will now also be called when `beforeSession` itself fails — the hook can inspect the session to detect this case (no entries beyond the initial user message will have been processed).

## [0.3.0] - 2026-09-29

**Upgrading from 0.2.x.** Nothing is removed and no existing signature changes, but check these before you bump:

- `OrchestratorHooks` gains two optional members, `beforeToolCall` and `onToolBudgetExhausted`. Code that checks the hooks exhaustively, for example `satisfies Record<keyof OrchestratorHooks, …>`, fails to type-check until it names both.
- `ToolRegistry.execute` now validates tool input against each tool's `inputSchema`, so a tool that produced its own message for malformed input receives only valid input; the model reads the registry's validation message instead.
- `maxToolRounds` now counts executed rounds: the default of 5 runs 5 tool rounds, not 6. Raise it by one to keep the old count.
- Offering a bare access token as the only WebSocket subprotocol still works but is deprecated: offer `hal.v1` beside it now, because the next minor release stops accepting a bare token.
- New dependencies: `ajv`, and `cookie` moves from `^0.7` to `^2`.

### Added

- `VertexConfig` gains an optional `apiEndpoint` field, forwarded verbatim to the `@google-cloud/vertexai` SDK constructor. Deployers who must keep inference in the EU multi-region can set `apiEndpoint: 'aiplatform.eu.rep.googleapis.com'`; the change is additive and the default behaviour (endpoint derived from `location`) is unchanged.
- `HalEngineConfig.transport` now accepts three optional extension points: `additionalRoutes` (mounts a router under `basePath`, unauthenticated), `rootRoutes` (mounts a router at `/`, after the `basePath` router and before the 404 catch-all), and `errorHandler` (replaces Express's default HTML error page). Pass none of them and the app is identical to before. See `docs/getting-started.md` for usage and the GDPR / NIS-2 notes that apply to unauthenticated routes.
- `OrchestratorHooks` gains an optional `beforeToolCall(session, call)` hook that fires before each known tool's executor, once per call per round. Return `undefined` to let the call run, or a `ToolResponse` to decline it: the executor is skipped and the model reads your `result` as that call's `tool_result`, with `clientMessages` and `suppressAssistantResponse` behaving as a tool's would. A hook that throws declines the call instead of failing the turn. Use it for an audit of what the model attempted or an EU AI Act Article 14 human-oversight control. The hook receives the model's raw tool input and, through `session`, the caller's `authHeaders`, so don't log either. Additive: with no hook installed, nothing changes.
- `OrchestratorHooks` gains an optional `onToolBudgetExhausted(session, budget)` hook, and `ToolBudgetInfo` (`{maxToolRounds, requestedTools}`) and `TOOL_BUDGET_EXHAUSTED` are exported. It fires when the model asks for a tool round `maxToolRounds` refuses, after the last provider call and before `afterModelResponse`. Return a sentence and the turn ends on it as an ordinary assistant entry, so the user sees a degraded answer instead of silence; the engine writes no prose of its own. Every exhausted run now also ends with a `{type: 'stop', stopReason: 'tool_budget_exhausted'}` chunk, a new value for the existing field rather than a new type, which the WebSocket transport sends nothing for. The turn still ends with `stream_end`, never `error`. Additive: with no hook installed, the wire is unchanged.
- `AssistantEntry` and `ThinkingEntry` gain an optional `truncated: true`, set on an entry the run could not finish: a provider failure mid-stream, or a round that ends on a tool call with no `stop`. The server re-sends such an entry as an `entry_upsert` carrying the flag just before its `entry_commit`, and the flag stays on the stored entry, so a client can render a cut-off answer as cut off live or on a replay, without relying on the transient `error` frame. An entry committed normally never carries it; a suppressed entry is flagged in the session but never re-sent. Text the thinking-tag parser was still holding back is now kept in a cut-off entry, as it already was on a normal stop. Additive: a client that ignores the field renders what it did before, and the extra `entry_upsert` replaces the entry with the content it already has.

### Changed

- Every `user_message` now ends in exactly one `stream_end`, including a run that fails and a message that fails validation; the `error` frame is advisory rather than terminal. Unparseable JSON remains the one frame answered with `INVALID_FORMAT` and no `stream_end`. **Migration note**: `stream_end` may now follow an `error` frame, so treat `stream_end` (or the socket closing) as the only end of a run. The one live consumer handles the two frame types independently, and both clear its processing state, so it keeps working unchanged and no deprecation period is served by delaying.
- Every assistant and thinking entry a run opens is now committed when the run ends, however it ends: a provider that throws mid-stream, or a round that ends on a tool call with no `stop`, no longer leaves an entry with `isStreaming: true` in the session. The partial content is kept exactly as streamed, and on a throw its `entry_commit` arrives before the `error` frame. **Migration note**: `entry_commit` now arrives on paths that previously sent none, so a client counting commit frames sees more of them. No wire type changes, and a client that already stops streaming on `stream_end` renders the same result.
- `maxToolRounds` now bounds the tool rounds that are actually executed: at most `maxToolRounds` rounds run, and the provider is called at most `maxToolRounds + 1` times. Previously the loop ran one extra round whose tool results no provider call ever read, so the default of 5 executed 6 rounds; it now executes 5, and the sixth provider call still reads the fifth round's results. `maxToolRounds: 0` now means one provider call and no tool execution, a negative value behaves as 0, and a non-finite value falls back to the default. When the budget runs out, the engine logs one `warn` (`tool budget exhausted`) naming the tools it did not run. **Migration note**: no exported type or signature changes, but a tool with a side effect in that final, unread round no longer runs there; to restore the old count, raise `maxToolRounds` by one.
- `HalEngineConfig.orchestrator.hooks` now carries a JSDoc comment. The field already shipped
  in `0.2.x`; the comment makes the lifecycle-hook seam discoverable from the published type
  declarations so editors surface it on hover without a trip to the README.
- `ToolRegistry.execute` now validates tool input against the declared `inputSchema` before invoking the executor. A schema-invalid call returns a descriptive `ToolResponse` to the model (naming the failing property path and constraint, never the value) rather than throwing, so the model can retry within the existing tool-round budget. Extra properties pass through to the executor unchanged. **Migration note**: an executor that previously hand-validated its own input now receives only input that has already passed the declared schema; a tool that relied on seeing malformed input to produce its own error message will no longer see it.
- The WebSocket server no longer echoes the access token in its handshake response. A client offers the new `hal.v1` marker beside its token (`new WebSocket(url, ['hal.v1', token])`, or `HAL_WS_SUBPROTOCOL`, now exported from the package root) and the server answers only `hal.v1`, so the token stays out of the 101 response headers and off the connected socket's `protocol` property. The token is read as the first offered value that is not the marker, in either order, and still reaches tools as `authHeaders.authorization`. `credentialFromSubprotocol`, also newly exported, reads it the same way for your own `WsAuthenticator`. **Migration note**: every client must be updated to offer `hal.v1` alongside its token, and an authenticator that took the first `Sec-WebSocket-Protocol` value as the token now gets `hal.v1` from an updated client, so read it with `credentialFromSubprotocol(req.headers['sec-websocket-protocol'])` instead. From the next MINOR, a client that offers only a bare token receives a 101 with no `Sec-WebSocket-Protocol` header, and `ws` and Chromium both fail such a handshake; this release still accepts a bare token (see Deprecated), because `0.2.x` documented it.

### Deprecated

- Offering a bare access token as the only WebSocket subprotocol. This release still echoes it and logs a warning that never includes the offered value; the next MINOR stops echoing it, and a client that has not added `hal.v1` will then fail its handshake.

## [0.2.1] - 2026-09-14

Identical to `0.2.0` — same files, same code. It exists to prove that a release publishes with no
credential stored in the repository: `0.2.0` had to be published with a token, because the registry
cannot hold a trusted publisher for a name that has never been published, and this is the first version
released through that publisher instead. There is nothing here to upgrade for.

## [0.2.0] - 2026-09-14

The first release under the `@re-cinq` scope. Nothing has been published before it, so there is no upgrade
path from `0.1.0` on the registry — only from the git specifier.

### Changed

- The published package carries no source maps. `files` is `["dist"]`, so every `.js.map` and `.d.ts.map`
  named a `../src/*.ts` the tarball did not contain and carried no inlined sources — 98 files that resolved
  to nothing in a debugger. Dropping them halves the file count. Step through the source from a checkout
  of the repository instead.

- The README documents the three environment variables this package actually reads — `CORS_ORIGIN`, `PORT`
  and `LOG_LEVEL` — each with its reading site, what overrides it, and its default. `AWS_REGION` and
  `GOOGLE_CLOUD_PROJECT` are gone from the provider docs: both are config fields, and setting the variable
  while passing a different `region` or `projectId` silently gives you the config value. Vendor credential
  variables are still listed, now stating that this package reads none of them — the vendor SDK does.

- The README now states which install path is supported. The registry specifier is the product; a git
  specifier builds from a checkout, carries no provenance, and pins a commit rather than a version. If you
  install from git under the key `hal-engine`, note that the rename is silent — `import 'hal-engine'` keeps
  working and `import '@re-cinq/hal-engine'` is what fails, because npm installs under the dependency key
  rather than the package name.

- **Log output is JSON, one object per line.** Lines were unstructured text (`[time] [LEVEL] [category] msg`),
  so `log.error` was indistinguishable from `log.info` to anything reading the stream. Each line now carries
  `severity`, `message`, `timestamp` and `category`, with the call site's fields under `data`. `ERROR` goes to
  stderr; every other level goes to stdout. If you parse this output, it has changed shape — see
  [docs/logging.md](docs/logging.md). Supply your own `logger` in `HalEngineConfig` to keep the old format, or
  any other — the option now reaches the package's own log calls, which it did not before this release. The
  swap is process-wide rather than per engine; `docs/logging.md` says why.

- The demo chat routes log a refusal. Every `401` emits one `warn` on category `http` carrying a fixed
  reason and nothing derived from the request, so a denied call is auditable without the log becoming a
  second place the request leaks.

